export function getSets(pool) {
  const map = {};
  pool.forEach(p => {
    if (!map[p.set]) map[p.set] = { set:p.set, name:p.setName, players:[] };
    map[p.set].players.push(p);
  });
  return Object.values(map).sort((a,b) => a.set-b.set);
}